CREATE TABLE CORE.T_AGG_PRODUCT_VARIANT_DISPOSAL_1 (
   WSHOP_CD                            VARCHAR(5)      NOT NULL COMMENT 'The unique code for the Lidl webshop, where an order can be placed by a customer.The webshop is defined per political country_1 and is run by an Lidl Digital Country_1',
   PROD_VARIANT_SID                    NUMBER          NOT NULL COMMENT 'Unique identifier (surrogate key) of the product variant',
   MATERIAL_DOC_MOV_PROCESS_TYPE_NAME  VARCHAR(50)     NOT NULL COMMENT 'Indicator of the process for which the material document has been created. Examples can be Verwertung (Recycling) or Verschrottung (Scrapping).',
   MATERIAL_DOC_MOV_PROCESS_SUBTYPE_NAME VARCHAR(200)    NOT NULL COMMENT 'Detailed explanation of the process for which the material document has been created. Example can be Recycling of old stock through Powerseller / Recycling through Greencycling',
   BOOKING_DT                          DATE            NOT NULL COMMENT 'Movement document date: date of goods issue or goods receipt registration in ERP System',
   PROD_VARIANT_NR                     VARCHAR(20)     COMMENT 'The product variant number',
   PROD_SID                            NUMBER          COMMENT 'Unique identifier (surrogate key) of the product',
   PROD_NR                             VARCHAR(20)     COMMENT 'The number for internal onlineshop product, which is country_1 independent',
   PROD_LOSS_NET_LOCAL_VAL             NUMBER(38, 5)   COMMENT 'Value amount of the loss generated by the material document line for the considered process.',
   PROD_REVENUE_NET_LOCAL_VAL          NUMBER(38, 5)   COMMENT 'Value amount of the revenue generated by the material document line for the considered process. For example, when we recycle a product we reclaim part of its original value as revenue',
   PROD_NET_LOCAL_VAL                  NUMBER(38, 5)   COMMENT 'Value in local currency (net) of material movement on position level of warehouse movement document which will be added or removed to/from the current value of the corresponding material stock. Value of total quantity of corresponding position.	',
   CURR_CD                             VARCHAR(5)      COMMENT 'The code identifying the currency according to ISO-4217.',
   PROD_QTY                            NUMBER(38, 0)   COMMENT 'Quantity of products in unit_1 measure (e.g. 1 unit_1 of product)',
   DWH_CREATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   DWH_UPDATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
   DWH_SRC_FILE_NAME                   VARCHAR(255)    NOT NULL COMMENT 'The path and the name of the file(s) from which this record was loaded.',
   SRC_FILE_TMSP                       TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was extracted from the source.',   
   CONSTRAINT PK_T_AGG_PRODUCT_VARIANT_DISPOSAL PRIMARY KEY (WSHOP_CD, PROD_VARIANT_SID, MATERIAL_DOC_MOV_PROCESS_TYPE_NAME, MATERIAL_DOC_MOV_PROCESS_SUBTYPE_NAME, BOOKING_DT) NOT ENFORCED 
)  COMMENT = 'A Fact table that aggregates value amount of loss and revenue for products which are being disposed of by recycling or scrapping. The granularity of the aggregation is at the level of webshop, product variant, movement process type (recycling or scrapping), movement process subtype (e.g. Powerseller), and booking date.';
